CREATE TABLE admins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE telegram_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, telegram_id BIGINT NOT NULL UNIQUE, username VARCHAR(255) NULL, first_name VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE domains (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, domain VARCHAR(255) NOT NULL UNIQUE, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE mailboxes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, telegram_user_id BIGINT UNSIGNED NULL, domain_id BIGINT UNSIGNED NOT NULL, email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, expires_at DATETIME NULL, status ENUM('active','expired','deleted') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_expiry(expires_at), FOREIGN KEY(domain_id) REFERENCES domains(id) ON DELETE RESTRICT, FOREIGN KEY(telegram_user_id) REFERENCES telegram_users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE emails (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, mailbox_id BIGINT UNSIGNED NOT NULL, message_uid VARCHAR(191) NOT NULL, sender VARCHAR(320) NULL, subject TEXT NULL, body_html LONGTEXT NULL, body_text LONGTEXT NULL, received_at DATETIME NULL, is_read TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uniq_mail_uid(mailbox_id,message_uid), FOREIGN KEY(mailbox_id) REFERENCES mailboxes(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE api_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, last_used_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, level VARCHAR(20) NOT NULL, message TEXT NOT NULL, context JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_level(level)) ENGINE=InnoDB;
